import { CapsuleGeometry, TorusGeometry, PointLight, MeshPhysicalNodeMaterial, Group } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'hub-journal-badge';

  // visual sub-group so we can animate lift/tilt without disturbing scenePosition
  const visual = new THREE.Group();
  visual.name = 'badge-visual';
  root.add(visual);

  // --- capsule body: machined-metal ink capsule label ---
  const capsuleRadius = 0.16;
  const capsuleLength = 0.5;
  const capsuleGeo = new CapsuleGeometry(capsuleRadius, capsuleLength, 6, 16);
  const capsuleMat = new MeshPhysicalNodeMaterial({
    color: colors.ink,
    roughness: 0.55,
    metalness: 0.45,
    clearcoat: 0.2,
    clearcoatRoughness: 0.4,
  });
  const capsuleMesh = new THREE.Mesh(capsuleGeo, capsuleMat);
  capsuleMesh.rotation.z = Math.PI / 2; // lay horizontal
  capsuleMesh.castShadow = false;
  visual.add(capsuleMesh);

  // --- accent edge light ring wrapping the capsule seam ---
  const ringGeo = new TorusGeometry(capsuleRadius * 1.02, 0.012, 8, 32);
  const ringMat = new MeshPhysicalNodeMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 1.6,
    roughness: 0.4,
    metalness: 0.2,
  });
  const ringLeft = new THREE.Mesh(ringGeo, ringMat);
  ringLeft.rotation.y = Math.PI / 2;
  ringLeft.position.x = -(capsuleLength / 2);
  visual.add(ringLeft);

  const ringRight = ringLeft.clone();
  ringRight.position.x = capsuleLength / 2;
  visual.add(ringRight);

  // node-local accent rim light (kept within intensity cap)
  const rimLight = new PointLight(colors.accent, 1.0, 3.0, 2.0);
  rimLight.position.set(0.3, 0.15, 0.6);
  visual.add(rimLight);

  // subtle back-key so ink capsule reads with form (kept below cap)
  const fillLight = new PointLight(colors.paper, 0.3, 3.0, 2.0);
  fillLight.position.set(-0.4, -0.2, 0.5);
  visual.add(fillLight);

  // --- decorative gear glb content loaded async, scaled small into capsule ---
  let loadedGltfScene = null;
  const contentHolder = new THREE.Group();
  contentHolder.scale.setScalar(0.09);
  visual.add(contentHolder);

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      loadedGltfScene = gltf.scene;
      loadedGltfScene.traverse((child) => {
        if (child.isMesh && child.material) {
          const mats = Array.isArray(child.material) ? child.material : [child.material];
          mats.forEach((m) => {
            if (m.roughness !== undefined) m.roughness = Math.max(m.roughness, 0.5);
            if (m.metalness !== undefined) m.metalness = Math.min(m.metalness, 0.55);
            if (m.clearcoat !== undefined) m.clearcoat = Math.min(m.clearcoat, 0.25);
          });
        }
      });
      contentHolder.add(loadedGltfScene);
    }).catch(() => {
      // silent fail - badge still reads via capsule + rim light
    });
  }

  // --- weighted-settle entrance ---
  visual.scale.setScalar(0.001);
  const entranceTl = gsap.timeline();
  entranceTl.to(visual.scale, {
    x: 1.04, y: 1.04, z: 1.04,
    duration: 0.55,
    ease: 'power3.out',
  }).to(visual.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });

  // idle breathing (single slow transform, <=2%)
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(visual.scale, {
    x: 1.015, y: 1.015, z: 1.015,
    duration: 3.2,
    ease: 'sine.inOut',
  });

  // --- cinematic primitives (generic loop, no inlined logic) ---
  const primitiveHandles = [];
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const p of primitiveList) {
    const fn = ctx.primitives?.[p.name];
    if (typeof fn === 'function') {
      const handle = fn(root, { ...(p.params ?? {}), trigger: p.trigger });
      if (handle) primitiveHandles.push(handle);
    }
  }

  // --- interaction handlers ---
  let hoverTween = null;
  const baseY = visual.position.y;

  root.userData.handlers = {
    hover: (isHovering) => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(visual.position, {
        y: isHovering ? baseY + 0.15 : baseY,
        duration: isHovering ? 0.3 : 0.4,
        ease: 'power2.out',
      });
      gsap.to(ringMat, {
        emissiveIntensity: isHovering ? 2.2 : 1.6,
        duration: 0.3,
        ease: 'power2.out',
      });
    },
    click: () => {
      const pressTl = gsap.timeline();
      pressTl.to(visual.scale, {
        x: 0.97, y: 0.97, z: 0.97,
        duration: 0.12,
        ease: 'back.out',
      }).to(visual.scale, {
        x: 1, y: 1, z: 1,
        duration: 0.2,
        ease: 'power2.out',
      });
      ctx.emit('navigate', { to: 'hub-journal' });
      ctx.emit('hub-journal.select', { id: config.id ?? 'hub-journal-badge' });
    },
  };

  // --- cleanup ---
  root.userData.cleanup = () => {
    entranceTl.kill();
    idleTl.kill();
    if (hoverTween) hoverTween.kill();

    for (const handle of primitiveHandles) {
      handle.timeline?.kill?.();
      handle.cleanup?.();
    }

    capsuleGeo.dispose();
    capsuleMat.dispose();
    ringGeo.dispose();
    ringMat.dispose();

    rimLight.dispose?.();
    fillLight.dispose?.();

    if (loadedGltfScene) {
      loadedGltfScene.traverse((child) => {
        if (child.isMesh) {
          child.geometry?.dispose?.();
          const mats = Array.isArray(child.material) ? child.material : [child.material];
          mats.forEach((m) => m?.dispose?.());
        }
      });
    }
  };

  return root;
}
